{"content": "#!/usr/bin/env python3
"""
Level-by-level MI verification - faster for detecting failures.
Checks MI on each level of the state graph separately.
"""
import sys
import time
from collections import deque

INV_CACHE = {}

def inv_table(n):
    t = INV_CACHE.get(n)
    if t is None:
        nv = 1 << n
        t = [0] * nv
        for v in range(nv):
            c = 0
            for i in range(n):
                if (v >> i) & 1:
                    for j in range(i + 1, n):
                        if not (v >> j) & 1:
                            c += 1
            t[v] = c
        INV_CACHE[n] = t
    return t


class Ctx:
    def __init__(self, n):
        self.n = n
        nv = 1 << n
        self.nv = nv
        self.ops = [(a, b) for a in range(n) for b in range(a + 1, n)]
        self.hi_mask = {}
        self.delta = {}
        for (a, b) in self.ops:
            m = 0
            for v in range(nv):
                if ((v >> a) & 1) and not ((v >> b) & 1):
                    m |= 1 << v
            self.hi_mask[(a, b)] = m
            self.delta[(a, b)] = (1 << b) - (1 << a)
        self.cube = (1 << nv) - 1
        self.inv = inv_table(n)

    def step(self, R, op):
        m = self.hi_mask[op]
        d = self.delta[op]
        hit = R & m
        return R if not hit else (R & ~m) | (hit << d)

    def levels_bfs(self, max_levels=None):
        """BFS level by level, returns list of sets per level."""
        levels = [{self.cube}]
        seen = {self.cube}
        while True:
            if max_levels is not None and len(levels) > max_levels:
                break
            cur = levels[-1]
            nxt = set()
            for R in cur:
                for op in self.ops:
                    R2 = self.step(R, op)
                    if R2 != R and R2 not in seen:
                        seen.add(R2)
                        nxt.add(R2)
            if not nxt:
                break
            levels.append(nxt)
        return levels


def check_MI_on_sets(ctx, sets):
    """Check MI on a collection of sets. Returns (fail_count, first_failure_details)."""
    inv = ctx.inv
    failures = 0
    first_fail = None

    for R in sets:
        for op in ctx.ops:
            a, b = op
            m = ctx.hi_mask[op]
            d = ctx.delta[op]
            wits = R & m
            if not wits:
                continue

            # Find min inversion among witnesses
            min_inv = ctx.n * ctx.n + 1
            w = wits
            while w:
                v = (w & -w).bit_length() - 1
                iv = inv[v]
                if iv < min_inv:
                    min_inv = iv
                w ^= 1 << v

            # Check if any min-inv witness is matched
            matched = False
            w = wits
            while w:
                v = (w & -w).bit_length() - 1
                iv = inv[v]
                if iv == min_inv:
                    partner = v + d
                    if R & (1 << partner):
                        matched = True
                        break
                w ^= 1 << v

            if not matched:
                failures += 1
                if first_fail is None:
                    first_fail = (R, op, min_inv, R.bit_count())

    return failures, first_fail


def main():
    n = 7
    print(f"=== Level-by-level MI check at n={n} ===", flush=True)
    t0 = time.time()

    ctx = Ctx(n)
    print("Building levels...", flush=True)
    levels = ctx.levels_bfs()
    t1 = time.time()
    print(f"Found {len(levels)} levels in {t1-t0:.2f}s", flush=True)

    total_sets = 0
    total_failures = 0
    all_failures = []

    for i, level in enumerate(levels):
        if i == 0:
            total_sets += len(level)
            continue
        t_lvl = time.time()
        fails, first = check_MI_on_sets(ctx, level)
        dt = time.time() - t_lvl
        total_sets += len(level)
        total_failures += fails
        if fails > 0:
            print(f"  Level {i}: {len(level):,} sets, {fails} MI failures ({dt:.2f}s)", flush=True)
            if first:
                R, op, minv, sz = first
                print(f"    First failure: size={sz}, op={op}, min_inv={minv}", flush=True)
        else:
            print(f"  Level {i}: {len(level):,} sets, clean ({dt:.2f}s)", flush=True)

    t_end = time.time()
    print(f"\nTotal: {total_sets:,} sets, {total_failures} MI failures", flush=True)
    print(f"Total time: {t_end - t0:.2f}s", flush=True)

    # Save details
    import json
    with open("agents/agent-090/n7_mi_levels.json", "w") as f:
        json.dump({
            "n": n,
            "n_levels": len(levels),
            "total_sets": total_sets,
            "total_failures": total_failures,
            "total_time": t_end - t0,
        }, f, indent=2)


if __name__ == "__main__":
    main()
